# Fresh preserved-Python output and independent algebra use the SAME saved
# whole-case indices. No fixture is generated by the native R implementation.
pl_cl_dir<-function() {
    root<-getOption("pathlab.root")
    if(!is.null(root))file.path(root,"modules/pathlab/tests/fixtures/categorical-logistic") else testthat::test_path("..","fixtures","categorical-logistic")
}
pl_cl_read<-function(name,suffix)jsonlite::fromJSON(file.path(pl_cl_dir(),paste0(name,"-",suffix,".json")),simplifyVector=FALSE)
pl_cl_data<-function(name)read.csv(file.path(pl_cl_dir(),paste0(name,".csv")),check.names=FALSE,stringsAsFactors=FALSE)
pl_cl_scalar<-function(v)if(is.character(v))paste0("s:",v) else sprintf("n:%.12g",v)
pl_cl_condition<-function(c)if(length(c))paste(sort(vapply(names(c),function(i)paste(i,pl_cl_scalar(c[[i]]),sep="="),"")),collapse="|") else ""
pl_cl_focal<-function(r) {
    f<-r$focal_contrast
    if(is.null(f))"" else paste(f$node_id,pl_cl_scalar(f$level),pl_cl_scalar(f$reference),sep="/")
}
pl_cl_route<-function(path)paste(unlist(path),collapse=">")
pl_cl_key<-function(r) {
    kind<-if(length(r$moderator_ids))r$effect_kind else r$kind
    paste(kind,if(kind=="specific_indirect")pl_cl_route(r$path_ids) else "",
          paste(sort(unlist(r$moderator_ids)),collapse=","),pl_cl_condition(r$condition),pl_cl_focal(r),sep="|")
}
pl_cl_matrix<-function(x)do.call(rbind,lapply(x,unlist))
pl_cl_betas<-function(ref,bootstrap=FALSE)lapply(if(bootstrap)ref$bootstrap_coefficients else ref$equations$false,function(v)if(bootstrap)pl_cl_matrix(v) else unlist(v$beta))
pl_cl_polynomial<-function(beta,level,condition,derivative,joint) {
    B<-function(target,j)if(is.matrix(beta[[target]]))beta[[target]][,j] else beta[[target]][j]
    k<-if(level==1)0L else 1L
    if(joint) {
        low<-as.numeric(condition$w=="low");z<-condition$z
        a<-if(length(derivative)) B("m1",9+k)+low*B("m1",11+k) else
            B("m1",3+k)+low*B("m1",6+k)+z*B("m1",9+k)+low*z*B("m1",11+k)
    } else {
        a<-B("m1",4+k)
        if(condition$w=="low")a<-a+B("m1",6+k)
        if(condition$w=="high")a<-a+B("m1",8+k)
    }
    zero<-0*a
    list(routes=list(a*B("y",2),if(length(derivative))zero else B("m2",3+k)*B("y",3),a*B("m2",2)*B("y",3)),
         direct=if(length(derivative))zero else B("y",4+k))
}
pl_cl_expected<-function(row,beta,joint) {
    condition<-row$condition
    if(!length(condition))condition<-if(joint)list(w="low",z=-.5) else list(w="low")
    p<-pl_cl_polynomial(beta,row$focal_contrast$level,condition,row$moderator_ids,joint)
    kind<-if(length(row$moderator_ids))row$effect_kind else row$kind
    routes<-c("p_x_m1>p_m1_y","p_x_m2>p_m2_y","p_x_m1>p_m1_m2>p_m2_y")
    switch(kind,specific_indirect=p$routes[[match(pl_cl_route(row$path_ids),routes)]],
           total_indirect=Reduce("+",p$routes),direct=p$direct,total=Reduce("+",p$routes)+p$direct)
}
pl_cl_terms<-function(eq)names(eq$terms)
pl_cl_python_term<-function(factors) {
    if(!length(factors))return("(Intercept)")
    paste(sort(vapply(factors,function(f)if(is.null(f$level))f$node_id else paste0(f$node_id,"@",match(f$level,if(f$node_id=="x")c(1,2,3) else c("low","middle","high"))-1L),"")),collapse=":")
}

for(case in c("categorical_linear","joint_linear","categorical_logistic","joint_logistic"))local({
    name<-case
    testthat::test_that(paste(name,"matches typed indicator bases Python and independent full covariance"),{
        q<-pl_cl_read(name,"request");ref<-pl_cl_read(name,"independent");pyall<-pl_cl_read(name,"python");d<-pl_cl_data(name)
        model<-validate_spec(q$graph,q$settings,names(d));sample<-prepare_sample(d,model);compiled<-compile_equations(model,sample)
        testthat::expect_identical(unname(sample$basis$x),c("x@0","x@2"))
        testthat::expect_equal(sample$basis_description[["x@0"]]$level,1)
        testthat::expect_equal(sample$basis_description[["x@0"]]$reference,2)
        testthat::expect_identical(sample$basis_description[["w@0"]]$level,"low")
        testthat::expect_identical(sample$basis_description[["w@0"]]$reference,"middle")
        testthat::expect_equal(sample$n,216)
        testthat::expect_length(sample$conditions,if(q$joint)4 else 3)
        testthat::expect_equal(unname(sample$probes$w),if(q$joint)c("low","middle") else c("low","middle","high"))
        for(robust in c(FALSE,TRUE)) {
            fitted<-fit_equations(compiled,robust);py<-pyall[[tolower(as.character(robust))]]
            for(target in names(fitted)) {
                eq<-fitted[[target]];terms<-pl_cl_terms(eq);order<-match(terms,unlist(ref$terms[[target]]))
                testthat::expect_false(anyNA(order))
                independent<-ref$equations[[tolower(as.character(robust))]][[target]]
                beta<-unlist(independent$beta);covariance<-pl_cl_matrix(independent$covariance)
                testthat::expect_equal(unname(eq$fit$coefficients),unname(beta[order]),tolerance=1e-8)
                testthat::expect_equal(unname(eq$fit$covariance),unname(covariance[order,order]),tolerance=1e-8)
                for(stat in c("se","statistic","p","lower","upper"))testthat::expect_equal(unname(eq$fit[[stat]]),unname(unlist(independent[[stat]])[order]),tolerance=1e-8)
                pe<-Filter(function(e)e$target_id==target,py$equations)[[1]]
                po<-match(terms,vapply(pe$coefficients,function(c)pl_cl_python_term(c$factors),""))
                testthat::expect_false(anyNA(po))
                testthat::expect_equal(unname(eq$fit$coefficients),vapply(pe$coefficients[po],function(c)c$estimate,0.0),tolerance=1e-8)
                testthat::expect_equal(unname(eq$fit$covariance),unname(pl_cl_matrix(pe$covariance$values)[po,po]),tolerance=1e-8)
                # Explicit independent R glm/lm fit on the expected indicator
                # matrix, followed by a separate manual HC3 calculation.
                expected_X<-matrix(0,nrow(d),length(order))
                x1<-as.numeric(d$x==1);x3<-as.numeric(d$x==3);low<-as.numeric(d$w=="low");high<-as.numeric(d$w=="high");one<-rep(1,nrow(d))
                if(target=="m1")expected_X<-if(q$joint)cbind(one,low,x1,x3,d$z,low*x1,low*x3,low*d$z,x1*d$z,x3*d$z,low*x1*d$z,low*x3*d$z) else cbind(one,low,high,x1,x3,low*x1,low*x3,high*x1,high*x3)
                if(target=="m2")expected_X<-cbind(one,d$m1,x1,x3)
                if(target=="y")expected_X<-cbind(one,d$m1,d$m2,x1,x3)
                X<-expected_X[,order,drop=FALSE];y<-d[[target]]
                testthat::expect_equal(unname(eq$design),unname(X),tolerance=1e-12)
                if(q$logistic && target=="y") {
                    independent_R<-stats::glm.fit(X,y,family=stats::binomial(),control=stats::glm.control(epsilon=1e-12,maxit=100))
                    testthat::expect_true(independent_R$converged)
                    probability<-independent_R$fitted.values;weights<-probability*(1-probability)
                    bread<-solve(crossprod(X,X*weights));hat<-weights*rowSums((X%*%bread)*X)
                    covariance_R<-if(robust)bread%*%crossprod(X,X*((y-probability)/(1-hat))^2)%*%bread else bread
                    for(stat in c("log_likelihood","null_log_likelihood","pseudo_R2","AIC","BIC"))testthat::expect_equal(eq$fit[[stat]],independent[[stat]],tolerance=1e-8)
                    testthat::expect_equal(eq$fit$fitted,probability,tolerance=1e-8)
                    testthat::expect_identical(eq$family,"logistic")
                } else {
                    independent_R<-stats::lm.fit(X,y);bread<-solve(crossprod(X));hat<-rowSums((X%*%bread)*X)
                    covariance_R<-if(robust)bread%*%crossprod(X,X*(independent_R$residuals/(1-hat))^2)%*%bread else bread*sum(independent_R$residuals^2)/(length(y)-ncol(X))
                    testthat::expect_identical(eq$family,"linear")
                }
                testthat::expect_equal(unname(eq$fit$coefficients),unname(independent_R$coefficients),tolerance=1e-8)
                testthat::expect_equal(unname(eq$fit$covariance),unname(covariance_R),tolerance=1e-8)
            }
            # Every explicitly declared path and interaction has its expanded
            # coefficient(s), with reference levels retained in the metadata.
            for(p in py$path_coefficients) {
                eq<-fitted[[p$target_id]];factor<-if(is.null(p$focal_contrast))p$source_id else paste0(p$source_id,"@",match(p$focal_contrast$level,if(p$source_id=="x")c(1,2,3) else c("low","middle","high"))-1L)
                j<-match(factor,names(eq$terms));testthat::expect_false(is.na(j))
                for(stat in c("se","statistic","p","lower","upper"))testthat::expect_equal(eq$fit[[stat]][j],p[[stat]],tolerance=1e-8,ignore_attr=TRUE)
                testthat::expect_equal(eq$fit$coefficients[j],p$estimate,tolerance=1e-8,ignore_attr=TRUE)
            }
            for(p in py$interaction_coefficients) {
                eq<-fitted[[p$target_id]];j<-match(pl_cl_python_term(p$factors),names(eq$terms));testthat::expect_false(is.na(j))
                testthat::expect_equal(eq$fit$coefficients[j],p$estimate,tolerance=1e-8,ignore_attr=TRUE)
                testthat::expect_equal(eq$fit$se[j],p$se,tolerance=1e-8,ignore_attr=TRUE)
            }
        }
    })

    testthat::test_that(paste(name,"shares all 200 draws and matches every route derivative and paired contrast"),{
        q<-pl_cl_read(name,"request");ref<-pl_cl_read(name,"independent");pyall<-pl_cl_read(name,"python");d<-pl_cl_data(name)
        indices<-as.matrix(read.csv(file.path(pl_cl_dir(),paste0(name,"-indices.csv")),header=FALSE))
        testthat::expect_equal(indices,as.matrix(read.csv(file.path(pl_cl_dir(),"categorical_linear-indices.csv"),header=FALSE)))
        testthat::expect_identical(dim(indices),c(200L,216L))
        testthat::expect_true(all(indices>=1 & indices<=216))
        beta<-pl_cl_betas(ref);boot<-pl_cl_betas(ref,TRUE)
        for(robust in c(FALSE,TRUE)) {
            r<-pathlab_fit(d,q$graph,q$settings,draws=200,seed=q$seed,robust=robust,indices=indices)
            py<-pyall[[tolower(as.character(robust))]]
            testthat::expect_equal(r$bootstrap$successful,200)
            testthat::expect_equal(r$bootstrap$failed,0)
            testthat::expect_equal(r$accepted_draws,1:200)
            testthat::expect_length(r$estimands,if(q$joint)194 else 90)
            testthat::expect_equal(anyDuplicated(vapply(r$estimands,function(x)x$id,"")),0L)
            for(target in names(r$equations))for(draw in c(1L,37L,200L)) {
                eq<-r$equations[[target]];order<-match(names(eq$terms),unlist(ref$terms[[target]]))
                actual<-pl_fit(eq$design[indices[draw,],,drop=FALSE],eq$y[indices[draw,]],coefficients_only=TRUE,family=eq$family)
                testthat::expect_equal(unname(actual),unname(boot[[target]][draw,order]),tolerance=1e-8)
            }
            expected<-list()
            for(row in r$estimands) {
                if(is.null(row$effect_a))expected[[row$id]]<-list(value=pl_cl_expected(row,beta,q$joint),draws=pl_cl_expected(row,boot,q$joint)) else {
                    a<-expected[[row$effect_a]];b<-expected[[row$effect_b]]
                    expected[[row$id]]<-list(value=a$value-b$value,draws=a$draws-b$draws)
                }
            }
            for(k in seq_along(r$estimands)) {
                row<-r$estimands[[k]];independent<-expected[[row$id]]
                testthat::expect_equal(row$estimate,unname(independent$value),tolerance=1e-8)
                testthat::expect_equal(r$bootstrap_distribution[,k],unname(independent$draws),tolerance=1e-8)
                testthat::expect_equal(row$bootstrap_se,stats::sd(independent$draws),tolerance=1e-8)
                testthat::expect_equal(c(row$lower,row$upper),unname(stats::quantile(independent$draws,c(.025,.975),type=7)),tolerance=1e-8)
            }
            originals<-Filter(function(x)is.null(x$effect_a),r$estimands)
            lookup<-setNames(originals,vapply(originals,pl_cl_key,""))
            testthat::expect_equal(length(lookup),length(py$effects)+length(py$indices))
            for(p in c(py$effects,py$indices)) {
                actual<-lookup[[pl_cl_key(p)]];testthat::expect_false(is.null(actual))
                for(stat in c("estimate","bootstrap_se","lower","upper"))testthat::expect_equal(actual[[stat]],p[[stat]],tolerance=1e-8)
            }
            contrasts<-Filter(function(x)!is.null(x$effect_a),r$estimands)
            pair_key<-function(a,b)paste(a,b,sep="|")
            pairs<-setNames(contrasts,vapply(contrasts,function(x)pair_key(x$effect_a,x$effect_b),""))
            for(group in c("effect_contrasts","index_contrasts")) {
                indexed<-group=="index_contrasts";sources<-if(indexed)py$indices else py$effects
                byid<-setNames(sources,vapply(sources,function(x)x$id,""))
                for(p in py[[group]]) {
                    a<-lookup[[pl_cl_key(byid[[if(indexed)p$index_a else p$effect_a]])]]
                    b<-lookup[[pl_cl_key(byid[[if(indexed)p$index_b else p$effect_b]])]]
                    actual<-pairs[[pair_key(a$id,b$id)]];sign<-1
                    if(is.null(actual)){actual<-pairs[[pair_key(b$id,a$id)]];sign<--1}
                    testthat::expect_false(is.null(actual))
                    testthat::expect_equal(actual$estimate,sign*p$estimate,tolerance=1e-8)
                    testthat::expect_equal(actual$bootstrap_se,p$bootstrap_se,tolerance=1e-8)
                    testthat::expect_equal(c(actual$lower,actual$upper),if(sign==1)c(p$lower,p$upper) else -c(p$upper,p$lower),tolerance=1e-8)
                }
            }
            testthat::expect_length(r$slopes,length(py$slopes))
            for(p in py$slopes) {
                actual<-Filter(function(x)x$path_id==p$path_id && pl_cl_condition(x$condition)==pl_cl_condition(p$condition) && pl_cl_focal(x)==pl_cl_focal(p),r$slopes)
                testthat::expect_length(actual,1)
                for(stat in c("estimate","se","p","lower","upper"))testthat::expect_equal(actual[[1]][[stat]],p[[stat]],tolerance=1e-8)
            }
            testthat::expect_length(r$johnson_neyman,length(py$johnson_neyman))
            for(p in py$johnson_neyman) {
                actual<-Filter(function(x)x$path_id==p$path_id && x$moderator_id==p$moderator_id && pl_cl_condition(x$other_conditions)==pl_cl_condition(p$other_conditions) && pl_cl_focal(x)==pl_cl_focal(p),r$johnson_neyman)
                testthat::expect_length(actual,1)
                if(p$moderator_id=="w") {
                    testthat::expect_identical(actual[[1]]$status,"not_applicable")
                    testthat::expect_true(nzchar(actual[[1]]$reason))
                    testthat::expect_length(actual[[1]]$boundaries,0)
                } else testthat::expect_equal(actual[[1]]$boundaries,as.numeric(unlist(p$boundaries)),tolerance=1e-8)
            }
        }
    })
})
